examples.code:
inventory = {"apples": 10}

# .get() with a default avoids a KeyError for a missing item
print(inventory.get("bananas", 0))   # 0

# Grouping words by their first letter, using setdefault
words = ["apple", "ant", "bear", "bee", "cat"]
groups = {}
for word in words:
    first_letter = word[0]
    groups.setdefault(first_letter, []).append(word)

print(groups)   # {'a': ['apple', 'ant'], 'b': ['bear', 'bee'], 'c': ['cat']}

